Facts current_facts()
{
    Facts facts;
    facts.languages        = available_languages();
    facts.running_language = wxGetApp().current_language_code().ToUTF8().data();
    const Updates::UpdateCheck::State update = Updates::update_check().state();
    facts.version        = update.version;
    facts.update_status  = status_name(update.status);
    facts.update_checked = update.last_success;
    if (update.available) {
        facts.update_version   = update.available->version;
        facts.update_url       = update.available->url;
        facts.update_published = update.available->published;
        facts.update_notes     = update.available->notes;
    }
    for (const Agent::ProviderProfile& profile : Agent::provider_profiles())
        if (!Agent::load_provider_api_key(wxGetApp().app_config, profile.id).empty())
            facts.configured_providers.push_back(profile.id);
    facts.versions_folder = (boost::filesystem::path(data_dir()) / "jusprin" / "projects").string();
#ifdef _WIN32
    facts.windows = true;
#endif
    facts.links_associated = links_associated();
    return facts;
}
    std::string update_published;
    std::string update_notes;
    // Where version history is kept.
    std::string versions_folder;
    // File and link associations are a Windows feature in OrcaSlicer.
    bool windows{false};
    // Whether this JusPrin opens the "Open in slicer" links of Printables
    // (prusaslicer://) and Thingiverse (cura://).
    bool links_associated{false};
    // Providers with a stored key, in setup's order: what a new chat can
    // start with.
    std::vector<std::string> configured_providers;
};

// The page's preferences payload: {kind: "preferences", ...}.
nlohmann::json snapshot(const AppConfig& config, const Facts& facts);

