28	constexpr const char* kSection = "jusprin_agent";
29	
30	// A server named here, such as a staging or self-hosted one, is the one the
31	// account signs in to instead of the default.
32	constexpr const char* kServerSection = "jusprin_server";
33	
34	std::string api_key_item_for(const std::string& provider) { return provider + "_api_key"; }
35	// An account provider keeps the account's email, its number and the wire
36	// format of each of its models beside the token.
37	std::string account_item_for(const std::string& provider) { return provider + "_account"; }
38	std::string formats_item_for(const std::string& provider) { return provider + "_model_formats"; }
39	std::string account_id_item_for(const std::string& provider) { return provider + "_account_id"; }
40	
41	// The server JUSPRIN_SERVER_URL names, otherwise the settings file's. The
42	// variable lets a test run reach a staging server without writing a settings
43	// file before launch.
44	std::string server_base_url(const AppConfig* config)
45	{
46	    if (const char* chosen = std::getenv("JUSPRIN_SERVER_URL"); chosen != nullptr && *chosen != '\0')
47	        return chosen;
48	    return config == nullptr ? std::string() : config->get(kServerSection, "base_url");
49	}
50	
51	// Where an account provider's gateway is: on the server named above, or the
52	// row's own.
53	std::string cloud_gateway(const AppConfig* config, const ProviderProfile& row)
54	{
55	    std::string base = server_base_url(config);
56	    while (!base.empty() && base.back() == '/')
57	        base.pop_back();
58	    return base.empty() ? row.endpoint : base + "/ent/jusprin/v2/responses";
59	}
60	
61	// The endpoint a provider is reached at, where it is not the row's: the
62	// developer's override for any provider, or an account provider's gateway.
63	std::string endpoint_for(const AppConfig* config, const ProviderProfile& profile)
64	{
65	    if (std::string override_endpoint = agent_endpoint_override(); !override_endpoint.empty())
66	        return override_endpoint;
67	    return profile.account_sign_in ? cloud_gateway(config, profile) : std::string();
68	}
69	
70	std::vector<std::pair<std::string, std::string>> stored_formats(const AppConfig* config, const std::string& provider)
71	{
72	    std::vector<std::pair<std::string, std::string>> formats;
73	    if (config == nullptr)
74	        return formats;
75	    const nlohmann::json stored = nlohmann::json::parse(config->get(kSection, formats_item_for(provider)), nullptr, false);
76	    if (stored.is_object())
77	        for (const auto& [model, format] : stored.items())
78	            if (format.is_string())
79	                formats.emplace_back(model, format.get<std::string>());
80	    return formats;
81	}
82	
83	void store_formats(AppConfig* config, const std::string& provider, const std::vector<std::pair<std::string, std::string>>& formats)
84	{
85	    nlohmann::json stored = nlohmann::json::object();
86	    for (const auto& [model, format] : formats)
87	        stored[model] = format;
88	    config->set(kSection, formats_item_for(provider), stored.dump());
89	}
90	
91	std::string stored_format(const AppConfig* config, const std::string& provider, const std::string& model)
92	{
93	    for (const auto& [listed, format] : stored_formats(config, provider))
94	        if (listed == model)
95	            return format;
96	    return {};
97	}
98	
99	void save_now(AppConfig& config);
100	
101	// Deletes a provider's stored key, and an account's email and formats with
102	// it. A chat without a choice of its own talks to the recorded provider; once
103	// its key is gone, that is the first provider that still has one. Remove and
104	// Sign out are drawn only on a stored key.
105	void remove_provider_key(AppConfig* config, const std::string& provider)
106	{
107	    if (config == nullptr)
108	        throw std::logic_error("jusprin-agent-setup: removing a key with no settings");
109	    if (config->get(kSection, api_key_item_for(provider)).empty())
110	        throw RuntimeError("jusprin-agent-setup: removing the key of " + provider + ", which has none stored");
111	    config->erase(kSection, api_key_item_for(provider));
112	    config->erase(kSection, account_item_for(provider));
113	    config->erase(kSection, formats_item_for(provider));
114	    config->erase(kSection, account_id_item_for(provider));
115	    if (provider == account_provider().id)
116	        sentry_set_account({});
117	    if (config->get(kSection, "provider") == provider)
118	        for (const ProviderProfile& profile : provider_profiles())
119	            if (!config->get(kSection, api_key_item_for(profile.id)).empty()) {
120	                config->set(kSection, "provider", profile.id);
121	                break;
122	            }
123	    // Saved now, as a stored key is: the person was just told it is gone.
124	    save_now(*config);
125	}
126	
127	ProviderListeners logging_listeners()
128	{
129	    ProviderListeners listeners;
130	    // Refused tool calls never reach a card or the activity list; the log is
131	    // where a wrong call can be read afterwards.
132	    listeners.refusal = [](const std::string& tool, const std::string& arguments, const std::string& code) {
133	        BOOST_LOG_TRIVIAL(warning) << "Agent tool call refused (" << code << "): " << tool << " " << arguments.substr(0, 1024);
134	    };
135	    listeners.request = request_log_writer(std::filesystem::u8path(data_dir()) / "jusprin" / "request-log");
136	    return listeners;
137	}
138	
139	// Writes the settings file at once. AppConfig::save() leaves the settings
140	// unsaved when the file could not be written.
141	void save_now(AppConfig& config)
142	{
143	    config.save();
144	    if (config.dirty())
145	        throw std::runtime_error("AppConfig::save() could not write the settings file");
146	}
147	
148	bool configured_true(const AppConfig* config, const char* key)
149	{
150	    if (config == nullptr)
151	        return false;
152	    const std::string value = config->get(kSection, key);
153	    return value == "true" || value == "1";
154	}
