218	bool is_cloud_web_done(const AppConfig* config, const std::string& url)
219	{
220	    const std::string done = cloud_server_from_gateway(endpoint_for(config, account_provider())) + "/ent/jusprin/v2/web/done";
221	    return url.compare(0, done.size(), done) == 0 &&
222	           (url.size() == done.size() || std::string("/?#").find(url[done.size()]) != std::string::npos);
223	}
