235	std::string cloud_account_token(const AppConfig* config)
236	{
237	    return load_provider_api_key(config, account_provider().id);
238	}
239	
240	std::string cloud_account_id(const AppConfig* config)
241	{
242	    return config == nullptr ? std::string() : config->get(kSection, account_id_item_for(account_provider().id));
243	}
244	
245	CloudSignInPtr make_cloud_sign_in(AppConfig* config)
246	{
247	    const ProviderProfile& row     = account_provider();
248	    const std::string      gateway = endpoint_for(config, row);
249	    CloudAccountStore      store;
250	    store.load = [config, id = row.id]() -> std::optional<CloudAccountRecord> {
251	        if (config == nullptr)
252	            return std::nullopt;
253	        CloudAccountRecord record;
254	        record.token   = config->get(kSection, api_key_item_for(id));
255	        record.email   = config->get(kSection, account_item_for(id));
256	        record.formats = stored_formats(config, id);
257	        record.account_id = config->get(kSection, account_id_item_for(id));
258	        return record;
259	    };
260	    // Signing in is choosing the account as the Agent's provider, after the
261	    // account row told the person what goes to JusPrin and on to the model's
262	    // provider: the same choices and consent a verified key records.
263	    store.save = [config, id = row.id](const CloudAccountRecord& record) {
264	        config->set(kSection, api_key_item_for(id), record.token);
265	        config->set(kSection, account_item_for(id), record.email);
266	        store_formats(config, id, record.formats);
267	        config->set(kSection, account_id_item_for(id), record.account_id);
268	        sentry_set_account(record.account_id);
269	        config->set(kSection, "provider", id);
270	        config->set(kSection, "enabled", "true");
271	        config->set(kSection, "cloud_consent", "true");
272	        save_now(*config);
273	    };
274	    store.erase = [config, id = row.id]() { remove_provider_key(config, id); };
275	    auto agents = [row, gateway](const std::string& token, const std::string& model, const std::string& format) -> AgentServicePtr {
276	        const std::optional<ProviderProfile> served = account_profile(row, gateway, format);
277	        if (!served)
278	            return nullptr;
279	        return make_provider_agent(*served, token, model, {}, make_openai_http_transport(), logging_listeners());
280	    };
281	    return std::make_shared<CloudSignIn>(cloud_server_from_gateway(gateway), gateway, row.model, make_cloud_account_deps(),
282	                                         std::move(store), std::move(agents));
283	}
