52	// row's own.
53	std::string cloud_gateway(const AppConfig* config, const ProviderProfile& row)
54	{
55	    std::string base = server_base_url(config);
56	    while (!base.empty() && base.back() == '/')
57	        base.pop_back();
58	    return base.empty() ? row.endpoint : base + "/ent/jusprin/v2/responses";
