73	    if (config == nullptr)
74	        return formats;
75	    const nlohmann::json stored = nlohmann::json::parse(config->get(kSection, formats_item_for(provider)), nullptr, false);
76	    if (stored.is_object())
77	        for (const auto& [model, format] : stored.items())
78	            if (format.is_string())
79	                formats.emplace_back(model, format.get<std::string>());
80	    return formats;
