101	// Deletes a provider's stored key, and an account's email and formats with
102	// it. A chat without a choice of its own talks to the recorded provider; once
103	// its key is gone, that is the first provider that still has one. Remove and
104	// Sign out are drawn only on a stored key.
105	void remove_provider_key(AppConfig* config, const std::string& provider)
106	{
107	    if (config == nullptr)
108	        throw std::logic_error("jusprin-agent-setup: removing a key with no settings");
109	    if (config->get(kSection, api_key_item_for(provider)).empty())
110	        throw RuntimeError("jusprin-agent-setup: removing the key of " + provider + ", which has none stored");
111	    config->erase(kSection, api_key_item_for(provider));
112	    config->erase(kSection, account_item_for(provider));
113	    config->erase(kSection, formats_item_for(provider));
114	    config->erase(kSection, account_id_item_for(provider));
115	    if (provider == account_provider().id)
116	        sentry_set_account({});
117	    if (config->get(kSection, "provider") == provider)
118	        for (const ProviderProfile& profile : provider_profiles())
119	            if (!config->get(kSection, api_key_item_for(profile.id)).empty()) {
120	                config->set(kSection, "provider", profile.id);
121	                break;
122	            }
123	    // Saved now, as a stored key is: the person was just told it is gone.
124	    save_now(*config);
125	}
