131	    // where a wrong call can be read afterwards.
132	    listeners.refusal = [](const std::string& tool, const std::string& arguments, const std::string& code) {
133	        BOOST_LOG_TRIVIAL(warning) << "Agent tool call refused (" << code << "): " << tool << " " << arguments.substr(0, 1024);
