163	AgentRuntime load_agent_runtime(AppConfig* config)
164	{
165	    AgentSettings settings;
166	    settings.enabled       = configured_true(config, "enabled");
167	    settings.cloud_consent = configured_true(config, "cloud_consent");
168	    if (config != nullptr) {
169	        settings.provider = config->get(kSection, "provider");
170	        settings.model    = config->get(kSection, "model");
171	    }
172	    settings.api_key = load_provider_api_key(config, settings.provider.empty() ? "openai" : settings.provider);
173	    if (const ProviderProfile* profile = profile_for(settings.provider); profile != nullptr && profile->account_sign_in) {
174	        settings.format   = stored_format(config, profile->id, settings.model.empty() ? profile->model : settings.model);
175	        settings.endpoint = cloud_gateway(config, *profile);
176	    }
177	    AgentRuntime runtime = resolve_agent_runtime(settings, agent_endpoint_override(), &make_openai_http_transport, logging_listeners());
178	    runtime.setup        = make_agent_setup(config);
179	    return runtime;
180	}
