182	AgentSetupServicePtr make_agent_setup(AppConfig* config)
183	{
184	    // Committing is the only part of setup that touches the machine, so it
185	    // lives here rather than in the GUI-free probe. Reaching this point means
186	    // the user read what the dock says about the provider billing them and
187	    // about the key staying on this machine, and chose to continue: that is
188	    // the cloud consent load_agent_runtime() requires on the next launch.
189	    auto commit = [config](const SetupCredentials& credentials) {
190	        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
191	        config->set(kSection, "provider", credentials.provider);
192	        config->set(kSection, "enabled", "true");
193	        config->set(kSection, "cloud_consent", "true");
194	        if (!credentials.model.empty())
195	            config->set(kSection, "model", credentials.model);
196	        // Written now, not at the next routine save, so a crash after setup
197	        // does not lose a key the user was just told is stored.
198	        save_now(*config);
199	    };
200	    ProviderKeySetup::KeyStore keys;
201	    keys.load   = [config](const std::string& provider) { return load_provider_api_key(config, provider); };
202	    keys.remove = [config](const std::string& provider) { remove_provider_key(config, provider); };
203	    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit), std::move(keys),
204	                                              agent_endpoint_override(), ProviderKeySetup::Clock{},
205	                                              make_cloud_sign_in(config));
206	}
