296	class AppConfigChatModelSource final : public IChatModelSource
297	{
298	public:
299	    AppConfigChatModelSource(AppConfig* config, std::function<void(std::function<void()>)> post)
300	        : m_config(config), m_post(std::move(post)), m_cancelled(std::make_shared<std::atomic<bool>>(false))
301	    {}
302	    // A list still on its way is dropped rather than delivered to a host
303	    // that is gone.
304	    ~AppConfigChatModelSource() override { *m_cancelled = true; }
305	
306	    // Read each time: setup may have stored a key since the last turn.
307	    std::vector<std::string> configured_providers() const override
308	    {
309	        std::vector<std::string> providers;
310	        if (!configured_true(m_config, "enabled") || !configured_true(m_config, "cloud_consent"))
311	            return providers;
312	        for (const ProviderProfile& profile : provider_profiles())
313	            if (!load_provider_api_key(m_config, profile.id).empty())
314	                providers.push_back(profile.id);
315	        return providers;
316	    }
317	
318	    std::string default_provider() const override
319	    {
320	        const std::string provider = m_config == nullptr ? std::string() : m_config->get(kSection, "provider");
321	        return provider.empty() ? "openai" : provider;
322	    }
323	
324	    AgentServicePtr make_agent(const ChatModelChoice& choice) override
325	    {
326	        const ProviderProfile* row = profile_for(choice.provider);
327	        const std::string      key = load_provider_api_key(m_config, choice.provider);
328	        if (row == nullptr || key.empty())
329	            return nullptr;
330	        ProviderProfile profile = *row;
331	        profile.effort          = choice.effort;
332	        if (!row->account_sign_in)
333	            return make_provider_agent(profile, key, choice.model, agent_endpoint_override(), make_openai_http_transport(),
334	                                       logging_listeners());
335	        const std::optional<ProviderProfile> served = account_profile(profile, endpoint_for(m_config, *row), choice.format);
336	        if (!served)
337	            return nullptr;
338	        return make_provider_agent(*served, key, choice.model, {}, make_openai_http_transport(), logging_listeners());
339	    }
340	
341	    std::string model_format(const std::string& provider, const std::string& model) const override
342	    {
343	        return stored_format(m_config, provider, model);
344	    }
345	
346	    void fetch_account(AccountDone done) override
347	    {
348	        for (const std::string& provider : configured_providers()) {
349	            const ProviderProfile* profile = profile_for(provider);
350	            if (profile == nullptr || !profile->account_sign_in)
351	                continue;
352	            const std::string token = load_provider_api_key(m_config, provider);
353	            Agent::fetch_account(in_app_language(*profile), token, endpoint_for(m_config, *profile), m_cancelled,
354	                                 [post = m_post, done = std::move(done), config = m_config, provider,
355	                                  token](std::optional<nlohmann::json> account) {
356	                                     post([done, account = std::move(account), config, provider, token]() mutable {
357	                                         // The account signed out, or another signed in, while this
358	                                         // was read: the answer is not the one signed in now.
359	                                         if (load_provider_api_key(config, provider) == token)
360	                                             done(std::move(account));
361	                                     });
362	                                 });
363	            return;
364	        }
365	        done(std::nullopt);
366	    }
367	
368	    // Signed out, the server is asked with no token: it then offers sign-up.
369	    void fetch_account_box(AccountBoxDone done) override
370	    {
371	        const std::string url = cloud_server_from_gateway(endpoint_for(m_config, account_provider())) + "/ent/jusprin/v2/account_box";
372	        Agent::fetch_account_box(in_app_language(account_provider()), cloud_account_token(m_config), url, m_cancelled,
373	                                 [post = m_post, done = std::move(done)](std::optional<std::string> html) {
374	                                     post([done, html = std::move(html)]() mutable { done(std::move(html)); });
375	                                 });
376	    }
377	
378	    void delete_account(DeleteAccountDone done) override
379	    {
380	        const std::string token = cloud_account_token(m_config);
381	        if (token.empty()) {
382	            done(false);
383	            return;
384	        }
385	        Agent::delete_account(account_provider(), token, cloud_account_url(m_config), m_cancelled,
386	                              [post = m_post, done = std::move(done)](bool deleted) { post([done, deleted] { done(deleted); }); });
387	    }
388	
389	    void list_models(const std::string& provider, ModelsDone done) override
390	    {
391	        const ProviderProfile* profile = profile_for(provider);
392	        const std::string      key     = load_provider_api_key(m_config, provider);
393	        if (profile == nullptr || key.empty()) {
394	            done(false, {}, false, {});
395	            return;
396	        }
397	        fetch_model_list(*profile, key, endpoint_for(m_config, *profile), m_cancelled,
398	                         [post = m_post, done = std::move(done), provider, config = m_config,
399	                          account = profile->account_sign_in](ModelListResult result) {
400	                             if (!result.ok)
401	                                 BOOST_LOG_TRIVIAL(warning) << "Agent model list for " << provider << ": " << result.error;
402	                             post([done, result = std::move(result), provider, config, account]() mutable {
403	                                 // An account's list says which format each model
404	                                 // is served in now; chats not yet started go by it.
405	                                 if (account && result.ok && config != nullptr) {
406	                                     std::vector<std::pair<std::string, std::string>> formats;
407	                                     for (const ModelOption& option : result.models)
408	                                         formats.emplace_back(option.id, option.format);
409	                                     store_formats(config, provider, formats);
410	                                     save_now(*config);
411	                                 }
412	                                 done(result.ok, std::move(result.models), result.refused,
413	                                      std::move(result.update_message));
414	                             });
415	                         });
416	    }
417	
418	private:
419	    AppConfig*                                  m_config;
420	    std::function<void(std::function<void()>)>  m_post;
421	    std::shared_ptr<std::atomic<bool>>          m_cancelled;
422	};
423	
424	} // namespace
425	
426	std::shared_ptr<IChatModelSource> make_chat_model_source(AppConfig* config, std::function<void(std::function<void()>)> post)
427	{
428	    return std::make_shared<AppConfigChatModelSource>(config, std::move(post));
429	}
