void AgentHost::set_chat_model_source(std::shared_ptr<IChatModelSource> source)
{
    m_model_source = std::move(source);
    m_models.clear();
    m_agent_choice = installed_agent_choice();
}

ChatModelChoice AgentHost::default_chat_model() const
{
    ChatModelChoice fallback;
    fallback.provider = m_model_source->default_provider();
    if (const ProviderProfile* profile = profile_for(fallback.provider))
        fallback.model = profile->model;
    fallback.format = m_model_source->model_format(fallback.provider, fallback.model);
    return fallback;
}

std::optional<ChatModelChoice> AgentHost::installed_agent_choice() const
{
    if (!m_model_source || !m_agent)
        return std::nullopt;
    return default_chat_model();
}

ChatModelChoice AgentHost::chat_model_choice(const std::string& conversation_id) const
{
    const std::vector<std::string> configured = m_model_source->configured_providers();
    if (std::optional<ChatModelChoice> chosen = m_persistence.document().chat_model(conversation_id))
        // A provider whose key is gone falls back to the default.
        if (std::find(configured.begin(), configured.end(), chosen->provider) != configured.end()) {
            // A chat that has not sent a request yet goes by the format the
            // account is given now; use_chat_model() fixes it at the first.
            if (chosen->format.empty())
                chosen->format = m_model_source->model_format(chosen->provider, chosen->model);
            return *chosen;
        }
    return new_chat_model();
}

ChatModelChoice AgentHost::new_chat_model() const
{
    ChatModelChoice choice = default_chat_model();
    const ProviderProfile* profile = profile_for(choice.provider);
    if (!profile || !profile->account_sign_in || !m_account)
        return choice;
    // On the account: Expert during the first month, Standard after it (board 6a).
    // The first-month lot stays in the answer until it expires, spent or not.
    const json& lots = m_account->at("credits").at("lots");
    if (std::any_of(lots.begin(), lots.end(), [](const json& lot) { return lot.at("kind") == "signup"; }))
        return choice;
    if (const auto held = m_models.find(choice.provider); held != m_models.end())
        for (const ModelOption& option : held->second.models)
            if (option.tier == "basic") {
                choice.model  = option.id;
                choice.effort = option.default_effort;
                choice.format = m_model_source->model_format(choice.provider, choice.model);
                break;
            }
    return choice;
}

void AgentHost::send_active_chat_model()
{
    if (!m_handshake)
        return;
    const std::string active = m_persistence.document().active_conversation_id();
    send_envelope(Protocol::kChatModel, json{{"conversationId", active}, {"chatModel", chat_model_json(active)}}.dump());
}

json AgentHost::chat_model_json(const std::string& conversation_id) const
{
    // A chat the person has talked in stays on its provider (use_chat_model),
    // so its greyed picker still names the model it ran on once that
    // provider's key is gone or its account signed out of. The page's model
    // list no longer has the provider, so its name goes with the choice.
    if (const std::optional<ChatModelChoice> kept = m_persistence.document().chat_model(conversation_id); kept) {
        const std::vector<std::string> configured = m_model_source->configured_providers();
        if (std::find(configured.begin(), configured.end(), kept->provider) == configured.end() &&
            person_talked_before(conversation_id, {})) {
            const ProviderProfile* profile = profile_for(kept->provider);
            return json{{"provider", kept->provider}, {"model", kept->model}, {"effort", kept->effort},
                        {"providerLabel", profile ? profile->display_name : kept->provider}};
        }
    }
    const ChatModelChoice choice = chat_model_choice(conversation_id);
    return json{{"provider", choice.provider}, {"model", choice.model}, {"effort", choice.effort}};
}

void AgentHost::request_model_lists()
{
    for (const std::string& provider : m_model_source->configured_providers()) {
        const auto held = m_models.find(provider);
        if (held != m_models.end() && held->second.state != ProviderModels::State::Failed)
            continue;
        m_models[provider] = ProviderModels{};
        m_model_source->list_models(provider, [this, provider](bool ok, std::vector<ModelOption> models, bool refused,
                                                               std::string update_message) {
            ProviderModels& entry = m_models[provider];
            entry.state          = ok ? ProviderModels::State::Ready : ProviderModels::State::Failed;
            entry.models         = std::move(models);
            entry.update_message = std::move(update_message);
            // A refused list is a key or sign-in that no longer works, as a
            // refused turn is. Any other failure leaves it standing: for the
            // JusPrin account, Preferences then says AI is unavailable.
            if (refused)
                reject_saved_key(provider);
            if (m_handshake)
                send_model_catalog();
            send_active_chat_model();
        });
    }
}

void AgentHost::send_model_catalog()
{
    json providers = json::array();
    for (const std::string& provider : m_model_source->configured_providers()) {
        const ProviderProfile* profile = profile_for(provider);
        if (profile == nullptr)
            continue;
        const auto held = m_models.find(provider);
        const char* state = held == m_models.end() || held->second.state == ProviderModels::State::Loading ? "loading" :
                            held->second.state == ProviderModels::State::Ready                             ? "ready" :
                                                                                                             "failed";
        json models = json::array();
        if (held != m_models.end())
            for (const ModelOption& option : held->second.models) {
                json model{{"id", option.id}, {"label", option.label}, {"efforts", option.efforts}};
                if (!option.default_effort.empty())
                    model["defaultEffort"] = option.default_effort;
                if (!option.tier.empty())
                    model["tier"] = option.tier;
                if (option.credits)
                    model["credits"] = *option.credits;
                if (!option.images)
                    model["images"] = false;
                models.push_back(std::move(model));
            }
        json entry{{"id", provider}, {"label", profile->display_name}, {"defaultModel", profile->model},
                   {"state", state}, {"models", std::move(models)}};
        if (held != m_models.end() && !held->second.update_message.empty())
            entry["updateMessage"] = held->second.update_message;
        providers.push_back(std::move(entry));
    }
    send_envelope(Protocol::kModelCatalog,
                  json{{"defaultProvider", m_model_source->default_provider()}, {"providers", std::move(providers)}}.dump());
}

void AgentHost::handle_set_chat_model(const std::string& envelope_id, const std::string& payload_json)
{
    const json payload = json::parse(payload_json);
    ChatModelChoice choice{payload.at("provider").get<std::string>(), payload.at("model").get<std::string>(),
                           payload.value("effort", "")};
    if (!m_model_source)
        throw RuntimeError("jusprin-agent-bridge: set_chat_model without the model_choice capability");
    const std::vector<std::string> configured = m_model_source->configured_providers();
    // The pickers list configured providers only; any other is a broken page.
    if (std::find(configured.begin(), configured.end(), choice.provider) == configured.end() || choice.model.empty())
        throw RuntimeError("jusprin-agent-bridge: set_chat_model names a provider that is not set up: " + choice.provider);
    ProjectStateDocument& document = m_persistence.document();
    const std::string conversation_id = document.active_conversation_id();
    // A chat keeps the format its model was first served in through a change
    // of thinking level. Another model starts unfixed and is fixed by the
    // chat's next request.
    if (const std::optional<ChatModelChoice> stored = document.chat_model(conversation_id);
        stored && stored->provider == choice.provider && stored->model == choice.model)
        choice.format = stored->format;
    document.set_chat_model(conversation_id, choice);
    m_persistence.commit();
    send_envelope(Protocol::kChatModel,
                  json{{"conversationId", conversation_id}, {"chatModel", chat_model_json(conversation_id)}}.dump(),
                  envelope_id);
}

bool AgentHost::person_started(const ConversationMessage& assistant) const
{
    const std::optional<ConversationMessage> source = find_stored_message(assistant.in_reply_to);
    return !source || source->role != MessageRole::Note;
}

// Whether the person sent a message before the one this turn answers, as the
// page counts them for greying the model pickers: a message the gateway
// returned to the composer does not count.
bool AgentHost::person_talked_before(const std::string& conversation_id, const std::string& in_reply_to) const
{
    const std::vector<ConversationMessage> messages = m_persistence.document().messages(conversation_id);
    return std::any_of(messages.begin(), messages.end(), [&](const ConversationMessage& message) {
        return message.role == MessageRole::User && !message.returned && message.id != in_reply_to;
    });
}

// The app's own turns read the plate picture, so they run on the account's
// Expert alias whatever the chat's model is or will be.
ChatModelChoice AgentHost::app_turn_model(const ChatModelChoice& chat) const
{
    ChatModelChoice expert;
    expert.provider = chat.provider;
    if (const auto held = m_models.find(chat.provider); held != m_models.end())
        for (const ModelOption& option : held->second.models)
            if (option.tier == "expert") {
                expert.model  = option.id;
                expert.effort = option.default_effort;
                break;
            }
    if (expert.model.empty())
        if (const ProviderProfile* profile = profile_for(chat.provider))
            expert.model = profile->model;
    expert.format = m_model_source->model_format(chat.provider, expert.model);
    return expert;
}

bool AgentHost::model_reads_pictures(const ChatModelChoice& choice) const
{
    const auto held = m_models.find(choice.provider);
    if (held == m_models.end())
        return true;
    for (const ModelOption& option : held->second.models)
        if (option.id == choice.model)
            return option.images;
    return true;
}

