        json models = json::array();
        if (held != m_models.end())
            for (const ModelOption& option : held->second.models) {
                json model{{"id", option.id}, {"label", option.label}, {"efforts", option.efforts}};
                if (!option.default_effort.empty())
                    model["defaultEffort"] = option.default_effort;
                if (!option.tier.empty())
                    model["tier"] = option.tier;
                if (option.credits)
                    model["credits"] = *option.credits;
                if (!option.images)
                    model["images"] = false;
                models.push_back(std::move(model));
            }
        json entry{{"id", provider}, {"label", profile->display_name}, {"defaultModel", profile->model},
                   {"state", state}, {"models", std::move(models)}};
        if (held != m_models.end() && !held->second.update_message.empty())
            entry["updateMessage"] = held->second.update_message;
        providers.push_back(std::move(entry));
    }
    send_envelope(Protocol::kModelCatalog,
                  json{{"defaultProvider", m_model_source->default_provider()}, {"providers", std::move(providers)}}.dump());
}

void AgentHost::handle_set_chat_model(const std::string& envelope_id, const std::string& payload_json)
{
    const json payload = json::parse(payload_json);
    ChatModelChoice choice{payload.at("provider").get<std::string>(), payload.at("model").get<std::string>(),
                           payload.value("effort", "")};
    if (!m_model_source)
        throw RuntimeError("jusprin-agent-bridge: set_chat_model without the model_choice capability");
    const std::vector<std::string> configured = m_model_source->configured_providers();
    // The pickers list configured providers only; any other is a broken page.
    if (std::find(configured.begin(), configured.end(), choice.provider) == configured.end() || choice.model.empty())
        throw RuntimeError("jusprin-agent-bridge: set_chat_model names a provider that is not set up: " + choice.provider);
    ProjectStateDocument& document = m_persistence.document();
    const std::string conversation_id = document.active_conversation_id();
    // A chat keeps the format its model was first served in through a change
    // of thinking level. Another model starts unfixed and is fixed by the
    // chat's next request.
    if (const std::optional<ChatModelChoice> stored = document.chat_model(conversation_id);
        stored && stored->provider == choice.provider && stored->model == choice.model)
        choice.format = stored->format;
    document.set_chat_model(conversation_id, choice);
    m_persistence.commit();
    send_envelope(Protocol::kChatModel,
                  json{{"conversationId", conversation_id}, {"chatModel", chat_model_json(conversation_id)}}.dump(),
                  envelope_id);
}

bool AgentHost::person_started(const ConversationMessage& assistant) const
{
    const std::optional<ConversationMessage> source = find_stored_message(assistant.in_reply_to);
    return !source || source->role != MessageRole::Note;
}

// Whether the person sent a message before the one this turn answers, as the
// page counts them for greying the model pickers: a message the gateway
// returned to the composer does not count.
bool AgentHost::person_talked_before(const std::string& conversation_id, const std::string& in_reply_to) const
{
    const std::vector<ConversationMessage> messages = m_persistence.document().messages(conversation_id);
    return std::any_of(messages.begin(), messages.end(), [&](const ConversationMessage& message) {
        return message.role == MessageRole::User && !message.returned && message.id != in_reply_to;
    });
}

// The app's own turns read the plate picture, so they run on the account's
// Expert alias whatever the chat's model is or will be.
ChatModelChoice AgentHost::app_turn_model(const ChatModelChoice& chat) const
{
    ChatModelChoice expert;
    expert.provider = chat.provider;
    if (const auto held = m_models.find(chat.provider); held != m_models.end())
        for (const ModelOption& option : held->second.models)
            if (option.tier == "expert") {
                expert.model  = option.id;
                expert.effort = option.default_effort;
                break;
            }
    if (expert.model.empty())
        if (const ProviderProfile* profile = profile_for(chat.provider))
            expert.model = profile->model;
    expert.format = m_model_source->model_format(chat.provider, expert.model);
    return expert;
}

bool AgentHost::model_reads_pictures(const ChatModelChoice& choice) const
{
    const auto held = m_models.find(choice.provider);
    if (held == m_models.end())
        return true;
    for (const ModelOption& option : held->second.models)
        if (option.id == choice.model)
            return option.images;
    return true;
}

