        CHECK(resolve_agent_runtime(settings, "", &null_transport).unavailable_reason ==
              "Cloud Agent access requires explicit consent.");
        settings.enabled = false;
        CHECK(resolve_agent_runtime(settings, "", &null_transport).unavailable_reason == "The Agent is not enabled.");
    }
}

TEST_CASE("JUSPRIN_AGENT_ENDPOINT redirects the Agent, and JUSPRIN_OPENAI_ENDPOINT still does", "[agent][providers]")
{
    {
        ScopedEnvironment agent("JUSPRIN_AGENT_ENDPOINT", nullptr);
        ScopedEnvironment openai("JUSPRIN_OPENAI_ENDPOINT", nullptr);
        CHECK(agent_endpoint_override().empty());
    }
    {
        ScopedEnvironment agent("JUSPRIN_AGENT_ENDPOINT", nullptr);
        ScopedEnvironment openai("JUSPRIN_OPENAI_ENDPOINT", "http://127.0.0.1:1/v1/responses");
        CHECK(agent_endpoint_override() == "http://127.0.0.1:1/v1/responses");
    }
    {
        ScopedEnvironment agent("JUSPRIN_AGENT_ENDPOINT", "http://127.0.0.1:2/v1/responses");
        ScopedEnvironment openai("JUSPRIN_OPENAI_ENDPOINT", "http://127.0.0.1:1/v1/responses");
        CHECK(agent_endpoint_override() == "http://127.0.0.1:2/v1/responses");
    }

    // The override reaches the agent of whichever provider is stored.
    struct Capture final : IAgentHttpTransport
    {
        explicit Capture(std::string& url) : url(url) {}
        bool post(AgentHttpRequest request, EventFn) override
        {
            url = request.url;
            return true;
        }
        void cancel() override {}
        std::string& url;
    };
    std::string  url;
    AgentRuntime runtime = resolve_agent_runtime(configured("openrouter"), "http://127.0.0.1:3/v1/responses",
                                                 [&url]() -> std::unique_ptr<IAgentHttpTransport> { return std::make_unique<Capture>(url); });
    AgentRequest request;
    JusPrinTest::kept_nowhere(request);
    request.request_id = "r";
    request.user_text  = "hi";
    REQUIRE(runtime.service->start(request));
    CHECK(url == "http://127.0.0.1:3/v1/responses");
}

// Preferences › BYOAI's group for a model the person runs on this computer
// (canvas "JusPrin v2": Agent/A Model on This Computer, approved 2026-11-24).
// The host finds the models at an address and checks the one picked; the
// page only mirrors where that has got to (local_status) and what is stored
// (setup_keys' local).

import { KeyboardEvent, useEffect, useRef, useState } from 'react';
import { plural, t } from '@lingui/core/macro';
import { Trans } from '@lingui/react/macro';
import { LocalModelChoice, LocalModelInfo, LocalStatusPayload } from '../bridge/protocol';

export const OLLAMA_ADDRESS = 'http://127.0.0.1:11434';

// The address as the sentences show it: without http:// and with no path.
export function shownAddress(address: string): string {
  return address.replace(/^[a-z]+:\/\//i, '').replace(/\/.*$/, '');
}

export interface LocalModelGroupProps {
  saved: LocalModelInfo | null;
  status: LocalStatusPayload;
  onFind: (address: string) => void;
  onCheck: (model: string) => void;
  onCancel: () => void;
  onRemove: () => void;
  // Opens the guide's section on a model's tools and context.
  onHelp: () => void;
}

interface FoundList {
  address: string;
  runtime: string;
  models: LocalModelChoice[];
}

function connectedLine(runtime: string, address: string): string {
  if (runtime === 'Ollama') return t`Ollama at ${address}`;
  if (runtime === 'LM Studio') return t`LM Studio at ${address}`;
  return t`The app at ${address}`;
}

function listLine(list: FoundList): string {
  const address = shownAddress(list.address);
  const count = list.models.length;
  if (list.runtime === 'Ollama') {
    if (count === 0) return t`Ollama at ${address} has no models. Download one in Ollama, then find models again.`;
    return plural(count, {
      one: `Ollama at ${address} has # model. Pick the one your chats should use.`,
      other: `Ollama at ${address} has # models. Pick the one your chats should use.`,
    });
  }
  if (list.runtime === 'LM Studio') {
    if (count === 0) return t`LM Studio at ${address} has no models. Download one in LM Studio, then find models again.`;
    return plural(count, {
      one: `LM Studio at ${address} has # model. Pick the one your chats should use.`,
      other: `LM Studio at ${address} has # models. Pick the one your chats should use.`,
    });
  }
  if (count === 0) return t`The app at ${address} has no models. Download one in that app, then find models again.`;
  return plural(count, {
    one: `The app at ${address} has # model. Pick the one your chats should use.`,
    other: `The app at ${address} has # models. Pick the one your chats should use.`,
  });
}

function requirementLine(runtime: string): string {
  if (runtime === 'Ollama') return t`The model must support tools, and its context length in Ollama must be at least 32k.`;
  if (runtime === 'LM Studio') return t`The model must support tools, and its context length in LM Studio must be at least 32k.`;
  return t`The model must support tools, and its context length in the app that runs it must be at least 32k.`;
}

export function LocalModelGroup({ saved, status, onFind, onCheck, onCancel, onRemove, onHelp }: LocalModelGroupProps) {
  const [form, setForm] = useState<'closed' | 'address' | 'models'>('closed');
  const [address, setAddress] = useState(OLLAMA_ADDRESS);
  const [list, setList] = useState<FoundList | null>(null);
  const [picked, setPicked] = useState('');
  // Which request the host's status speaks for: the page's last one, until
  // the person changes what it was about.
  const [sent, setSent] = useState<'find' | 'check' | null>(null);
  const input = useRef<HTMLInputElement>(null);

  const close = () => {
    setForm('closed');
    setList(null);
    setSent(null);
  };

  useEffect(() => {
    if (sent === 'find' && status.phase === 'models') {
      const found = { address: status.address ?? address, runtime: status.runtime ?? '', models: status.models ?? [] };
      setList(found);
      setForm('models');
      const keep = found.models.find((model) => model.id === saved?.model);
      setPicked(keep ? keep.id : found.models[0]?.id ?? '');
      setSent(null);
    }
    if (sent === 'check' && status.phase === 'verified') close();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status]);

  useEffect(() => {
    if (form === 'address') input.current?.focus();
  }, [form]);

  const finding = sent === 'find' && status.phase === 'finding';
  const checking = sent === 'check' && status.phase === 'checking';
  const failed = status.phase === 'error' ? status.error?.message : undefined;
  const addressError = form === 'address' && sent === 'find' ? failed : undefined;
  const checkError = form === 'models' && sent === 'check' ? failed : undefined;

  const find = (from: string) => {
    if (!from.trim() || finding) return;
    setSent('find');
    onFind(from.trim());
  };
  const cancel = () => {
    if (finding || checking) onCancel();
    close();
  };
  const keyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') find(address);
    if (event.key === 'Escape') cancel();
  };

  const connected = saved !== null && form === 'closed';
  const model = saved?.model ?? '';
  const pickedModel = picked;

  return (
    <section className="agent-group" aria-label={t`A model on this computer`}>
      <div className="agent-group-head">
        <h2 className="agent-group-title">{t`A model on this computer`}</h2>
        <p className="agent-group-intro">
          {t`Use a model you run yourself with Ollama, LM Studio or a similar app. Your messages go to that app, not to an online AI service, and there is nothing to pay. Local models are slower and make more mistakes than the cloud models above.`}
        </p>
      </div>
      <div className="agent-row" data-testid="agent-local">
        <div className="agent-row-line">
          <div className="agent-row-copy">
            <span className="agent-row-name">{t`Local model`}</span>
            {connected ? (
              <>
                <span className="agent-row-status agent-row-status--saved" data-testid="agent-local-standing">
                  <span className="agent-row-status-label">
                    <span className="jp-icon jp-icon-check" aria-hidden="true" />
                    <span>{t`Chats can use`}</span>
                  </span>
                  <code className="agent-key-hint">{model}</code>
                </span>
                <span className="agent-row-status agent-local-where">{connectedLine(saved.runtime, saved.address)}</span>
              </>
            ) : (
              <span className="agent-row-status">{t`Not set up`}</span>
            )}
          </div>
          {form === 'closed' && (saved === null ? (
            <button type="button" className="agent-row-action" onClick={() => setForm('address')}>
              <span className="jp-icon jp-icon-plus" aria-hidden="true" />
              {t`Set up`}
            </button>
          ) : (
            <div className="agent-row-actions">
              <button type="button" className="agent-row-action" onClick={() => {
                const from = `http://${saved.address}`;
                setAddress(from);
                setForm('address');
                find(from);
              }}>{t`Change`}</button>
              <button type="button" className="agent-row-action agent-row-action--danger" onClick={onRemove}>{t`Remove`}</button>
            </div>
          ))}
        </div>

        {connected && !saved.images && (
          <p className="agent-row-note">{t`This model can’t see pictures, so the AI works without seeing your model.`}</p>
        )}

        {form === 'address' && (
          <div className="agent-key-form">
            <label className="agent-key-label" htmlFor="agent-local-address">{t`Address of the app that runs the model`}</label>
            <div className={`agent-key-field${finding ? ' agent-key-field--locked' : addressError ? ' agent-key-field--error' : ''}`}>
              <input ref={input} id="agent-local-address" className="agent-key-input" value={address} disabled={finding}
                readOnly={finding} aria-invalid={addressError ? true : undefined} spellCheck={false}
                onChange={(event) => {
                  setAddress(event.target.value);
                  setSent(null);
                }}
                onKeyDown={keyDown} />
            </div>
            {addressError ? (
              <p className="agent-key-error" role="alert" data-testid="local-error">{addressError}</p>
            ) : (
              <p className="agent-row-note">
                <Trans>This is Ollama’s address. For LM Studio, use <code className="agent-key-hint">http://127.0.0.1:1234</code>.</Trans>
              </p>
            )}
            <div className="agent-key-actions">
              {finding ? (
                <span className="agent-key-checking">{t`Looking for models at ${shownAddress(address)}…`}</span>
              ) : (
                <button type="button" className="primary" onClick={() => find(address)} disabled={!address.trim()}>
                  {t`Find models`}
                </button>
              )}
              <button type="button" className="link" onClick={cancel}>{t`Cancel`}</button>
            </div>
          </div>
        )}

        {form === 'models' && list && (
          <div className="agent-key-form">
            <p className="agent-row-note">{listLine(list)}</p>
            {list.models.length > 0 && (
              <fieldset className="agent-local-list" disabled={checking} aria-label={t`Model`}>
                {list.models.map((choice) => (
                  <label key={choice.id}
                    className={`agent-local-option${choice.id === picked ? ' agent-local-option--picked' : ''}`}>
                    <input type="radio" name="agent-local-model" checked={choice.id === picked}
                      onChange={() => {
                        setPicked(choice.id);
                        setSent(null);
                      }} />
                    <span className="agent-local-option-copy">
                      <code className="agent-local-option-name">{choice.id}</code>
                      <span className="agent-local-option-detail">
                        {choice.images ? t`Can see pictures` : t`Can’t see pictures. The AI works without seeing your model.`}
                      </span>
                    </span>
                  </label>
                ))}
              </fieldset>
            )}
            <p className="agent-row-note">
              {requirementLine(list.runtime)}{' '}
              <button type="button" className="link prefs-inline-link" onClick={onHelp}>{t`How to check and change this`}</button>
            </p>
            {checkError && <p className="agent-key-error" role="alert" data-testid="local-error">{checkError}</p>}
            <div className="agent-key-actions">
              {checking ? (
                <span className="agent-key-checking">
                  {t`Checking ${pickedModel}. A local model can take a minute to answer the first time.`}
                </span>
              ) : (
                list.models.length > 0 && (
                  <button type="button" className="primary" disabled={!picked} onClick={() => {
                    setSent('check');
                    onCheck(picked);
                  }}>{t`Use this model`}</button>
                )
              )}
              <button type="button" className="link" onClick={cancel}>{t`Cancel`}</button>
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

#pragma once

// Setting up a model that runs on this computer, in an app such as Ollama or
// LM Studio that answers OpenAI's Responses API at a local address.
//
// Finding asks the app at the address for its models and, where the app is
// one the setup knows, which of them take tools and read pictures. Checking
// is building, as a key check is: one real request with every tool the chat
// offers goes to the model through the agent chats will use, then the app is
// asked how much context it loaded the model with. A model passes when it
// answers and its context holds the app's tools (32k).
//
// GUI-free and poll-driven, like ProviderKeySetup: the app's answers only
// queue, and poll() reads them on the owner's thread. The HTTP client and
// the settings are injected, so the tests drive it with recorded answers.

#include "AgentService.hpp"
#include "AgentTransport.hpp"

#include <chrono>
#include <cstdint>
#include <deque>
#include <functional>
#include <memory>
#include <mutex>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

// The model on this computer the person set up: where the app that runs it
// answers, the model's name as that app gives it, which app it is ("Ollama",
// "LM Studio", or empty when the app could not tell), and whether the model
// reads pictures.
struct LocalModelRecord
{
    std::string address;
    std::string model;
    std::string runtime;
    bool        images{true};

    bool operator==(const LocalModelRecord& other) const
    {
        return address == other.address && model == other.model && runtime == other.runtime && images == other.images;
    }
};

// One model the app at the address has. `tools` and `images` are unset when
// the app does not say.
struct LocalModelInfo
{
    std::string         id;
    std::optional<bool> tools;
    std::optional<bool> images;
};

struct LocalModelList
{
    std::string                 address; // normalized_local_address()
    std::string                 runtime; // "Ollama", "LM Studio" or empty
    std::vector<LocalModelInfo> models;
};

struct LocalSetupOutcome
{
    enum class Kind { Models, Checked, Failed } kind{Kind::Failed};
    LocalModelList   models;  // Models
    LocalModelRecord record;  // Checked: stored already
    AgentServicePtr  service; // Checked: idle, ready to install
    AgentError       error;   // Failed: local_unreachable() or local_cant_run()
    int              elapsed_ms{0};
};

// The smallest context that holds the app's tools and a turn's messages.
inline constexpr long kLocalMinContext = 32768;

inline constexpr const char* kRuntimeOllama   = "Ollama";
inline constexpr const char* kRuntimeLmStudio = "LM Studio";

class LocalModelSetup
{
public:
    // What the app answered one request with. status 0 with `error` set
    // means nothing answered.
    struct Answer
    {
        unsigned    status{0};
        std::string body;
        std::string error;
    };
    // One request to the app: "GET" or "POST" (with a JSON body). `done` is
    // called once, on any thread.
    using Fetch            = std::function<void(const std::string& method, const std::string& url, const std::string& body,
                                     std::function<void(Answer)> done)>;
    using TransportFactory = std::function<std::unique_ptr<IAgentHttpTransport>()>;
    struct Store
    {
        std::function<std::optional<LocalModelRecord>()> load;
        std::function<void(const LocalModelRecord&)>     store;
        std::function<void()>                            remove;
    };
    using Clock = std::function<std::chrono::steady_clock::time_point()>;

    LocalModelSetup(Fetch fetch, TransportFactory transport, Store store, Clock clock = {});
    ~LocalModelSetup();

    bool busy() const { return m_step != Step::Idle; }
    // Lists the models at `address` as the person typed it. Throws when busy.
    void find(const std::string& address);
    // Checks `model`, one of the last list's, at that list's address, and
    // stores it when it passes. Throws when busy or for a model not listed.
    void check(const std::string& model);
    void cancel();
    // At most one finished outcome. Throws for an answer that names nothing
    // the person can act on, after stopping; the caller's top handler
    // reports it.
    std::optional<LocalSetupOutcome> poll();

    std::optional<LocalModelRecord> saved() const;
    void                            remove();

private:
    enum class Step { Idle, Models, Version, Show, LmsModels, Probe, LoadedContext };
    // Where the app's answers wait for poll(). Shared with the requests in
    // flight, which may answer after the setup is gone.
    struct Answers
    {
        std::mutex         mutex;
        std::deque<Answer> queue;
        std::uint64_t      generation{0};
    };

    void                             request(const std::string& method, const std::string& path, const std::string& body = {});
    std::optional<LocalSetupOutcome> advance(const Answer& answer);
    std::optional<LocalSetupOutcome> next_show();
    std::optional<LocalSetupOutcome> start_probe();
    std::optional<LocalSetupOutcome> poll_probe();
    LocalSetupOutcome                failed(AgentError error);
    LocalSetupOutcome                checked();
    [[noreturn]] void                unexpected(const std::string& what, const Answer& answer);
    void                             stop();
    int                              elapsed_ms() const;

    Fetch            m_fetch;
    TransportFactory m_transport;
    Store            m_store;
    Clock            m_clock;

    std::shared_ptr<Answers> m_answers{std::make_shared<Answers>()};

    Step                                  m_step{Step::Idle};
    std::chrono::steady_clock::time_point m_started{};
    LocalModelList                        m_list;
    std::size_t                           m_showing{0}; // the model /api/show is asked about
    std::string                           m_checking;
    AgentServicePtr                       m_candidate;
};

} // namespace Slic3r::GUI::JusPrin::Agent

