  var KEEP=/^(local_status|setup_keys|model_catalog|chat_model|assistant_|bridge_error|hello_ack|tool_activity|message_added|agent_status)/;
  var t=setInterval(function(){
    var b=window.__jusprinBridge; if(!b||!b.deliver||b.__wrapped) return;
    var d=b.deliver.bind(b); b.__wrapped=true;
    b.deliver=function(env){
      try{var e=typeof env==='string'?JSON.parse(env):env;
        if(KEEP.test(e.type)){var p=JSON.stringify(e.payload); if(e.type==='assistant_delta') p=p.slice(0,200); else if(p.length>3000) p=p.slice(0,3000)+'…'; log({type:e.type,payload:p});}
      }catch(x){log({type:'wrap_error',payload:String(x)});}
      return d(env);
    };
    log({type:'wrapped'});
  },100);
  setInterval(function(){
    fetch(B+'/cmd?panel='+panel).then(function(r){return r.json();}).then(function(list){
      list.forEach(function(js){var out; try{out=String((0,eval)(js));}catch(x){out='ERR '+x;} log({type:'cmd_result',payload:out});});
    }).catch(function(){});
  },400);
})();
EOF
