"""Read and fill the empty entries of JusPrin's catalogs.
  po.py skeleton <localization dir> <out dir>   one <lang>.json per language: {"pages": {msgid: ""}, "native": {...}}
  po.py apply <localization dir> <in dir>       write each filled msgstr, marked "# AI Translated"
"""
import json, re, sys, pathlib

def unquote(lines):
    return ''.join(json.loads(l) for l in lines)

def parse(path):
    text = path.read_text(encoding='utf-8')
    blocks = text.split('\n\n')
    out = []
    for i, b in enumerate(blocks):
        lines = b.split('\n')
        try:
            mi = next(k for k, l in enumerate(lines) if l.startswith('msgid '))
            si = next(k for k, l in enumerate(lines) if l.startswith('msgstr '))
        except StopIteration:
            continue
        if any(l.startswith('msgid_plural') for l in lines):
            continue
        msgid = unquote([lines[mi][6:]] + [l for l in lines[mi+1:si] if l.startswith('"')])
        msgstr = unquote([lines[si][7:]] + [l for l in lines[si+1:] if l.startswith('"')])
        if msgid and not msgstr:
            out.append((i, msgid))
    return text, blocks, out

def langs(loc):
    return [l['code'] for l in json.loads((loc / 'languages.json').read_text())['languages'] if l['code'] != json.loads((loc / 'languages.json').read_text())['source']]

def main():
    cmd, loc, d = sys.argv[1], pathlib.Path(sys.argv[2]), pathlib.Path(sys.argv[3])
    for lang in langs(loc):
        if cmd == 'skeleton':
            data = {kind: {m: '' for _, m in parse(loc / kind / f'{lang}.po')[2]} for kind in ('pages', 'native')}
            (d / f'{lang}.json').write_text(json.dumps(data, ensure_ascii=False, indent=1), encoding='utf-8')
        else:
            data = json.loads((d / f'{lang}.json').read_text(encoding='utf-8'))
            for kind in ('pages', 'native'):
                path = loc / kind / f'{lang}.po'
                text, blocks, empty = parse(path)
                for i, msgid in empty:
                    value = data[kind].get(msgid, '')
                    if not value:
                        raise SystemExit(f'{lang} {kind}: no translation for {msgid!r}')
                    lines = blocks[i].split('\n')
                    si = next(k for k, l in enumerate(lines) if l.startswith('msgstr '))
                    lines = lines[:si] + ['msgstr ' + json.dumps(value, ensure_ascii=False)]
                    if not any(l == '# AI Translated' for l in lines):
                        lines = ['# AI Translated'] + lines
                    blocks[i] = '\n'.join(lines)
                path.write_text('\n\n'.join(blocks), encoding='utf-8')
main()
EOF
